steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": "
      {
        teams(first: 100) {
          nodes {
            id
            name
            key
            parent {
              id
              name
            }
            childTeams {
              nodes {
                id
                name
              }
            }
          }
        }
      }
    '
  }'
